// Los retenidos llegan de nuevo cada vez que Node-RED se reconecta:
// se descartan para no duplicar el historial
if (msg.retain) {
    return null;
}

const prefijo = "juegito/juegito-l01/";

msg.params = {
    $fecha: new Date().toISOString(),
    $topico: msg.topic.startsWith(prefijo) ? msg.topic.slice(prefijo.length) : msg.topic,
    $payload: String(msg.payload)
};
return msg;

const q = msg.req.query;

let limite = parseInt(q.limite, 10);
if (!(limite > 0)) {
    limite = 50;
}
limite = Math.min(limite, 500);

msg.params = {
    $limite: limite,
    $desde: parseInt(q.desde_id, 10) || 0,
    $topico: q.topico || null
};
return msg;

// El payload se guarda como texto; si es JSON se devuelve como objeto
msg.payload = {
    items: msg.payload.map(fila => {
        let payload;
        try {
            payload = JSON.parse(fila.payload);
        } catch (e) {
            payload = fila.payload;   // "online" / "offline"
        }
        return { id: fila.id, fecha: fila.fecha, topico: fila.topico, payload: payload };
    })
};
msg.headers = { "Content-Type": "application/json" };
return msg;

// Solo los errores de un pedido HTTP tienen a quien responder
if (!msg.res) {
    return null;
}
msg.statusCode = 500;
msg.payload = { error: msg.error.message };
return msg;
